#include <iostream>
#include <cstdint>

// Recursive Fibonacci demonstration
std::uint64_t fibonacci(std::uint64_t number) {
    if (number == 0 || number == 1) {
        return number; // Base cases: 0 and 1
    }
    // Order of evaluating operand 1 vs operand 2 is unspecified by C++,
    // but safe here because calls are pure functions without side effects.
    return fibonacci(number - 1) + fibonacci(number - 2);
}

int main() {
    for (unsigned int counter = 0; counter <= 10; ++counter) {
        std::cout << "fibonacci( " << counter << " ) = " 
                  << fibonacci(counter) << "\n";
    }
    return 0;
}

#include <iostream>
#include <iomanip>
#include <cstdint>

// Iterative factorial implementation (avoids call stack overhead)
std::uint64_t factorialIterative(unsigned int number) {
    std::uint64_t result = 1;
    for (unsigned int i = number; i >= 1; --i) {
        result *= i;
    }
    return result;
}

int main() {
    for (unsigned int counter = 0; counter <= 10; ++counter) {
        std::cout << std::setw(2) << counter << "! = " 
                  << factorialIterative(counter) << "\n";
    }
    return 0;
}
